us_class = null;                                             foreach ($categories as $category):                                                 $cat_link = get_category_link( $category->term_id );                                                 $cat_name = esc_html( $category->name );                                                 $random_class = $category_class[array_rand($category_class)];                                                 do {                                                     $random_class = $category_class[array_rand($category_class)];                                                 } while ($random_class === $previous_class);                                                 $previous_class = $random_class;                                                 ?>                                                 <li class="list-inline-item"><a href="<?php echo $cat_link  ?>" class="btn btn-sm <?php echo $random_class ?>"><?php echo $cat_name ?></a></li>                                             <?php endforeach; ?>                                         <?php else: ?>                                             <div class="alert alert-info">دسته بندی وجود ندارد!!</div>                                         <?php endif ?>                                     </ul>                                 </div>                                 <!-- Footer Widget -->                                 <div class="col-sm-6 col-lg-2 mb-4">                                     <h5 class="mb-4">شبکه های اجتماعی</h5>                                     <?php                                     $social_media_options = get_option('_shw_social_media_website', []);                                     $telegram = $social_media_options['telegram']?? '';                                     $instagram = $social_media_options['instagram']?? '';                                     $github = $social_media_options['github']?? '';                          